export interface ConnectorConfig {
  airtableApiKey: string
  baseId: string
  tableNameOrId: string
  fetch?: typeof fetch
}

export interface JotformSubmission {
  email: string
  first_name?: string
  last_name?: string
  phone?: string
  address?: string
}

export interface HandleResult {
  recordId: string
  updatedFields: string[]
}

function buildAirtableUrl(baseId: string, tableNameOrId: string, recordId?: string): string {
  const encodedTable = encodeURIComponent(tableNameOrId)
  const base = `https://api.airtable.com/v0/${baseId}/${encodedTable}`
  return recordId ? `${base}/${recordId}` : base
}

function buildFilterFormula(email: string): string {
  const escaped = email.replace(/'/g, "\\'")
  return `{Email}='${escaped}'`
}

async function fetchWithAuth(
  url: string,
  options: RequestInit,
  apiKey: string,
  fetchFn: typeof fetch
): Promise<Response> {
  const headers = new Headers(options.headers)
  headers.set('Authorization', `Bearer ${apiKey}`)
  if (options.body && !headers.has('Content-Type')) {
    headers.set('Content-Type', 'application/json')
  }
  return fetchFn(url, { ...options, headers })
}

export async function handle(payload: JotformSubmission, config: ConnectorConfig): Promise<HandleResult> {
  const fetchFn = config.fetch ?? fetch

  if (!payload.email || typeof payload.email !== 'string') {
    throw new Error('Missing required field: email')
  }

  const listUrl = buildAirtableUrl(config.baseId, config.tableNameOrId)
  const filterFormula = buildFilterFormula(payload.email)
  const listUrlWithFilter = `${listUrl}?filterByFormula=${encodeURIComponent(filterFormula)}`

  const listResponse = await fetchWithAuth(listUrlWithFilter, { method: 'GET' }, config.airtableApiKey, fetchFn)

  if (!listResponse.ok) {
    throw new Error(`Airtable list records failed: ${listResponse.status} ${listResponse.statusText} at GET ${listUrlWithFilter}`)
  }

  const listData = await listResponse.json() as { records: Array<{ id: string; fields: Record<string, unknown> }> }

  if (!listData.records || listData.records.length === 0) {
    throw new Error(`No Airtable record found for email: ${payload.email}`)
  }

  if (listData.records.length > 1) {
    throw new Error(`Multiple Airtable records found for email: ${payload.email} (expected unique)`)
  }

  const record = listData.records[0]
  const existingFields = record.fields

  const fieldMapping: Array<{ jotformKey: keyof JotformSubmission; airtableField: string }> = [
    { jotformKey: 'first_name', airtableField: 'First Name' },
    { jotformKey: 'last_name', airtableField: 'Last Name' },
    { jotformKey: 'phone', airtableField: 'Phone' },
    { jotformKey: 'address', airtableField: 'Address' }
  ]

  const fieldsToUpdate: Record<string, string> = {}
  const updatedFieldNames: string[] = []

  for (const mapping of fieldMapping) {
    const jotformValue = payload[mapping.jotformKey]
    const airtableValue = existingFields[mapping.airtableField]

    if (jotformValue && typeof jotformValue === 'string' && jotformValue.trim() !== '') {
      const isEmpty = airtableValue === undefined || airtableValue === null || airtableValue === ''
      if (isEmpty) {
        fieldsToUpdate[mapping.airtableField] = jotformValue.trim()
        updatedFieldNames.push(mapping.airtableField)
      }
    }
  }

  if (Object.keys(fieldsToUpdate).length === 0) {
    return { recordId: record.id, updatedFields: [] }
  }

  const patchUrl = buildAirtableUrl(config.baseId, config.tableNameOrId, record.id)
  const patchBody = JSON.stringify({ fields: fieldsToUpdate })

  const patchResponse = await fetchWithAuth(patchUrl, { method: 'PATCH', body: patchBody }, config.airtableApiKey, fetchFn)

  if (!patchResponse.ok) {
    throw new Error(`Airtable patch record failed: ${patchResponse.status} ${patchResponse.statusText} at PATCH ${patchUrl}`)
  }

  return { recordId: record.id, updatedFields: updatedFieldNames }
}

import { describe, it, expect, vi } from 'vitest'
import { handle, ConnectorConfig, JotformSubmission } from './connector'
import { SOURCE_EXAMPLE, contractFetch, fakeFetch, jsonResponse, TARGET_ENDPOINTS } from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      airtableApiKey: 'test-api-key',
      baseId: 'appTestBase',
      tableNameOrId: 'TestTable',
      fetch
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as JotformSubmission, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.recordId).toBe('recXXXXXXXXXXXXXX')
  })
})

describe('handle', () => {
  it('validates required email field', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({}, 200))
    const config: ConnectorConfig = {
      airtableApiKey: 'test-key',
      baseId: 'appBase',
      tableNameOrId: 'Table',
      fetch
    }
    const payload = { first_name: 'John' } as JotformSubmission
    await expect(handle(payload, config)).rejects.toThrow('Missing required field: email')
    expect(calls.length).toBe(0)
  })

  it('throws on non-2xx list response', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ error: 'Unauthorized' }, 401))
    const config: ConnectorConfig = {
      airtableApiKey: 'test-key',
      baseId: 'appBase',
      tableNameOrId: 'Table',
      fetch
    }
    const payload: JotformSubmission = { email: 'user@example.com' }
    await expect(handle(payload, config)).rejects.toThrow('Airtable list records failed: 401 Unauthorized')
    expect(calls.length).toBe(1)
    expect(calls[0].method).toBe('GET')
    expect(calls[0].url).toContain('filterByFormula')
  })

  it('throws when no record found', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ records: [] }, 200))
    const config: ConnectorConfig = {
      airtableApiKey: 'test-key',
      baseId: 'appBase',
      tableNameOrId: 'Table',
      fetch
    }
    const payload: JotformSubmission = { email: 'missing@example.com' }
    await expect(handle(payload, config)).rejects.toThrow('No Airtable record found for email: missing@example.com')
    expect(calls.length).toBe(1)
  })

  it('throws when multiple records found', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({
      records: [
        { id: 'rec1', fields: { Email: 'user@example.com' } },
        { id: 'rec2', fields: { Email: 'user@example.com' } }
      ]
    }, 200))
    const config: ConnectorConfig = {
      airtableApiKey: 'test-key',
      baseId: 'appBase',
      tableNameOrId: 'Table',
      fetch
    }
    const payload: JotformSubmission = { email: 'user@example.com' }
    await expect(handle(payload, config)).rejects.toThrow('Multiple Airtable records found')
    expect(calls.length).toBe(1)
  })

  it('happy path: finds record and patches only empty fields', async () => {
    const existingRecord = {
      id: 'rec123',
      fields: {
        Email: 'user@example.com',
        'First Name': '',
        'Last Name': 'Doe',
        Phone: '555-000-0000',
        Address: ''
      }
    }
    const { fetch, calls } = fakeFetch((req) => {
      if (req.method === 'GET' && req.url.includes('filterByFormula')) {
        return jsonResponse({ records: [existingRecord] }, 200)
      }
      if (req.method === 'PATCH' && req.url.endsWith('/rec123')) {
        expect(req.json).toEqual({ fields: { 'First Name': 'John', Address: '123 Main St' } })
        return jsonResponse({ id: 'rec123', fields: { ...existingRecord.fields, 'First Name': 'John', Address: '123 Main St' } }, 200)
      }
      return jsonResponse({ error: 'not found' }, 404)
    })
    const config: ConnectorConfig = {
      airtableApiKey: 'test-key',
      baseId: 'appBase',
      tableNameOrId: 'Table',
      fetch
    }
    const payload: JotformSubmission = {
      email: 'user@example.com',
      first_name: 'John',
      last_name: 'Smith',
      phone: '555-123-4567',
      address: '123 Main St'
    }
    const result = await handle(payload, config)
    expect(result.recordId).toBe('rec123')
    expect(result.updatedFields).toEqual(['First Name', 'Address'])
    expect(calls.length).toBe(2)
    expect(calls[0].method).toBe('GET')
    expect(calls[1].method).toBe('PATCH')
    expect(calls[1].headers.get('authorization')).toBe('Bearer test-key')
    expect(calls[1].headers.get('content-type')).toBe('application/json')
  })

  it('skips PATCH when no fields to update', async () => {
    const existingRecord = {
      id: 'rec123',
      fields: {
        Email: 'user@example.com',
        'First Name': 'John',
        'Last Name': 'Doe',
        Phone: '555-123-4567',
        Address: '123 Main St'
      }
    }
    const { fetch, calls } = fakeFetch((req) => {
      if (req.method === 'GET') {
        return jsonResponse({ records: [existingRecord] }, 200)
      }
      return jsonResponse({ error: 'should not patch' }, 404)
    })
    const config: ConnectorConfig = {
      airtableApiKey: 'test-key',
      baseId: 'appBase',
      tableNameOrId: 'Table',
      fetch
    }
    const payload: JotformSubmission = {
      email: 'user@example.com',
      first_name: 'Jane',
      last_name: 'Smith'
    }
    const result = await handle(payload, config)
    expect(result.recordId).toBe('rec123')
    expect(result.updatedFields).toEqual([])
    expect(calls.length).toBe(1)
    expect(calls[0].method).toBe('GET')
  })

  it('throws on non-2xx patch response', async () => {
    const existingRecord = {
      id: 'rec123',
      fields: { Email: 'user@example.com', 'First Name': '' }
    }
    const { fetch, calls } = fakeFetch((req) => {
      if (req.method === 'GET') {
        return jsonResponse({ records: [existingRecord] }, 200)
      }
      if (req.method === 'PATCH') {
        return jsonResponse({ error: 'Rate limited' }, 429)
      }
      return jsonResponse({}, 404)
    })
    const config: ConnectorConfig = {
      airtableApiKey: 'test-key',
      baseId: 'appBase',
      tableNameOrId: 'Table',
      fetch
    }
    const payload: JotformSubmission = { email: 'user@example.com', first_name: 'John' }
    await expect(handle(payload, config)).rejects.toThrow('Airtable patch record failed: 429 Too Many Requests')
    expect(calls.length).toBe(2)
  })

  it('handles URL encoding for table names with spaces', async () => {
    const existingRecord = { id: 'rec123', fields: { Email: 'user@example.com', 'First Name': '' } }
    const { fetch, calls } = fakeFetch((req) => {
      if (req.method === 'GET') {
        expect(req.url).toContain('Table%20Name')
        return jsonResponse({ records: [existingRecord] }, 200)
      }
      if (req.method === 'PATCH') {
        expect(req.url).toContain('Table%20Name/rec123')
        return jsonResponse({ id: 'rec123', fields: { Email: 'user@example.com', 'First Name': 'John' } }, 200)
      }
      return jsonResponse({}, 404)
    })
    const config: ConnectorConfig = {
      airtableApiKey: 'test-key',
      baseId: 'appBase',
      tableNameOrId: 'Table Name',
      fetch
    }
    const payload: JotformSubmission = { email: 'user@example.com', first_name: 'John' }
    await handle(payload, config)
    expect(calls.length).toBe(2)
  })

  it('uses injected fetch over global fetch', async () => {
    const globalFetch = vi.fn()
    const injectedFetch = vi.fn().mockResolvedValue(jsonResponse({ records: [{ id: 'rec1', fields: { Email: 'user@example.com', 'First Name': '' } }] }, 200))
    const config: ConnectorConfig = {
      airtableApiKey: 'test-key',
      baseId: 'appBase',
      tableNameOrId: 'Table',
      fetch: injectedFetch
    }
    const payload: JotformSubmission = { email: 'user@example.com', first_name: 'John' }
    await handle(payload, config)
    expect(injectedFetch).toHaveBeenCalled()
    expect(globalFetch).not.toHaveBeenCalled()
  })
})

